contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seedSupply, uint256 value) public {
        require(seedSupply > 0);
        require(value > 0);
        require(seedSupply >= value);
        c.mintToken(address(this), seedSupply); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= value);
        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        assert((!reverted && supplyBefore - supplyAfter == value && balBefore - balAfter == value)
            || (reverted && balBefore < value));
    }
    receive() external payable {}
}

