    }

    function _run(uint256 seedSupply, uint256 value) internal {
        vm.assume(seedSupply > 0);
        vm.assume(value > 0);
        vm.assume(seedSupply >= value);
        try c.mintToken(address(this), seedSupply) {} catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(balBefore >= value);
        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
