        try c.balanceOf(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue((!reverted && supplyBefore - supplyAfter == value && balBefore - balAfter == value)
            || (reverted && balBefore < value));
    }

    function testFuzz_run(uint256 seedSupply, uint256 value) public {
